// src/lib/plugin-version.ts
import { readFileSync } from "node:fs";
import { resolve } from "node:path";

// src/schemas/plugin-manifest.ts
var SEMVER_REGEX = /^\d+\.\d+\.\d+(-[\w.]+)?(\+[\w.]+)?$/;
var McpServerEntrySchema = external_exports.object({
  command: external_exports.string().min(1),
  args: external_exports.array(external_exports.string()).optional(),
  env: external_exports.record(external_exports.string(), external_exports.string()).optional()
}).passthrough();
var PluginManifestSchema = external_exports.object({
  name: external_exports.string().min(1),
  version: external_exports.string().regex(SEMVER_REGEX, "version must be semver (MAJOR.MINOR.PATCH)"),
  description: external_exports.string(),
  mcpServers: external_exports.record(external_exports.string(), McpServerEntrySchema),
  skills: external_exports.array(external_exports.string()).optional(),
  agents: external_exports.array(external_exports.string()).optional()
}).strict();

// src/lib/plugin-root.ts
import * as fs from "node:fs";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
function getPluginRoot() {
  const start = path.dirname(fileURLToPath(import.meta.url));
  let dir = start;
  const { root } = path.parse(dir);
  for (; ; ) {
    if (fs.existsSync(path.join(dir, ".claude-plugin", "plugin.json"))) {
      return dir;
    }
    if (dir === root) break;
    dir = path.dirname(dir);
  }
  throw new Error(
    `getPluginRoot: could not locate .claude-plugin/plugin.json above ${start}`
  );
}

// src/lib/plugin-version.ts
var cachedVersion;
function getPluginVersion() {
  if (cachedVersion !== void 0) {
    return cachedVersion;
  }
  const manifestPath = resolve(getPluginRoot(), ".claude-plugin/plugin.json");
  const raw = readFileSync(manifestPath, "utf8");
  const parsed = PluginManifestSchema.parse(JSON.parse(raw));
  cachedVersion = parsed.version;
  return cachedVersion;
}

